package com.acme.orders;

import java.util.List;
import java.util.Map;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class OrderController {

    private final OrderService orders;
    private final JdbcTemplate jdbc;

    public OrderController(OrderService orders, JdbcTemplate jdbc) {
        this.orders = orders;
        this.jdbc = jdbc;
    }

    @GetMapping("/orders/{id}")
    public Order get(@PathVariable long id) {
        return orders.find(id);
    }

    @GetMapping("/orders/{id}/lines")
    public List<Map<String, Object>> lines(@PathVariable long id) {
        return jdbc.queryForList("SELECT sku, qty FROM order_lines WHERE order_id = ?", id);
    }
}
